        .ToList();

    public IReadOnlyList<JsonElement> Lineas() =>
        Stdout.ToString().Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Select(l =>
            {
                using var d = JsonDocument.Parse(l);
                return d.RootElement.Clone();
            })
            .ToList();

